    pub open spec fn is_checked_out(&self, i: nat) -> bool {
        self.producer == ProducerState::Producing(i)
        || self.consumer == ConsumerState::Consuming(i)
    }


    pub open spec fn valid_storage_at_idx(&self, i: nat) -> bool {
