            #[cfg(verus_keep_ghost_body)]
            #[verifier::opaque] /* vattr */
            #[verus::internal(open)] /* vattr */
            #[verus::internal(verus_macro)]
            #[verifier::spec]
            pub fn init(post: #self_ty, #label_param) -> ::core::primitive::bool {
